        </v-col>
        <v-col cols="6" md="3" lg="3">
          <StatsWidget
            title="متوسط وقت الإنتظار"
            :number="homeData.data?.statistics?.companies_count || 0"
          >
            <template #icon>
              <svg width="44" height="44" viewBox="0 0 44 44" fill="none" xmlns="http://www.w3.org/2000/svg">
