        </v-col>
      </v-row>
      <!--  -->

      <v-row>
        <v-col cols="12">
          <VCard elevation="0" class="rounded-lg px-4 bg-light-white">
            <!-- Header Section -->
            <v-card-title class="pt-4 pb-6">
              <div class="">
                <div class="d-flex justify-space-between align-center">
                  <div
                    class="d-flex gap-2 border px-2 py-1"
                    style="border-radius: 16px; max-width: fit-content"
                  >
                    <v-btn
                      v-for="tab in [
                        { id: 'companies', label: 'الشركات ' },
                        { id: 'flights', label: 'الرحلات' },
                        { id: 'pilgrims', label: 'الحجاج' },
                      ]"
                      :key="tab.id"
                      elevation="0"
                      class="rounded-lg font-weight-bold"
                      :class="{
                        'bg-light-gray text-primary': activeTab === tab.id,
                        'bg-white text-gray-1': activeTab !== tab.id,
                      }"
                      @click="activeTab = tab.id"
                    >
                      <span class="responsive-text">{{ tab.label }}</span>
                    </v-btn>
                  </div>
                </div>
              </div>

              <!-- Content Section -->
              <v-window v-model="activeTab" class="mt-6">
                <!-- companies Tab -->
                <v-window-item value="companies">
                  <dataTable
                    :headers="headers"
                    :items="companies"
                    :loading="isLoading"
                    class="elevation-0"
                    :items-per-page="perPage"
                    v-model:page="currentPage"
                    :hide-default-footer="true"
                  >
                  <template #['item.actions']={item} >
                    <v-btn class="text-black" color="#fff" :prepend-icon="Editicon">
                      تعديل
                    </v-btn>
                  </template>
                  </dataTable>
                </v-window-item>

                <!-- flights Tab -->
                <v-window-item value="flights">
                  <v-row v-if="isLoading">
                    <v-col v-for="i in 6" :key="i" cols="12" sm="6" lg="4">
                      <v-skeleton-loader
                        class="mx-auto"
                        type="card"
                      ></v-skeleton-loader>
                    </v-col>
                  </v-row>
                  <v-row v-else-if="flights.length">
                    <v-col
                      v-for="travel in flights"
                      :key="travel.id"
                      cols="12"
                      sm="6"
                      lg="4"
                    >
                      <h1>travel</h1>
                    </v-col>
                  </v-row>
                  <v-row v-else>
                    <v-col cols="12" class="text-center">
                      <p class="text-medium-emphasis">لا توجد بيانات</p>
                    </v-col>
                  </v-row>
                </v-window-item>

                <!-- pilgrims Tab -->
                <v-window-item value="pilgrims">
                  <v-row v-if="isLoading">
                    <v-col v-for="i in 6" :key="i" cols="12" sm="6" lg="4">
                      <v-skeleton-loader
                        class="mx-auto"
                        type="card"
                      ></v-skeleton-loader>
                    </v-col>
                  </v-row>
                  <v-row v-else-if="pilgrims.length">
                    <v-col
                      v-for="pilgrim in pilgrims"
                      :key="pilgrim.id"
                      cols="12"
                      sm="6"
                      lg="4"
                    >
                      <h1>pilgrim</h1>
                    </v-col>
                  </v-row>
                  <v-row v-else>
                    <v-col cols="12" class="text-center">
                      <p class="text-medium-emphasis">لا توجد بيانات</p>
                    </v-col>
                  </v-row>
                </v-window-item>
              </v-window>

              <!-- Pagination -->
              <Pagination
                :total-items="totalItems"
                v-model:per-page="perPage"
                v-model:page="currentPage"
              />
            </v-card-title>
          </VCard>
        </v-col>
      </v-row>
    </v-container>
  </div>
</template>

